// Accept an event only if it is signed with WEBHOOK_SECRET (HMAC-SHA256 over the raw body)
// and its id was not accepted before. The sender may retry as often as it likes.
const crypto = require('crypto');
const secret = $env.WEBHOOK_SECRET;
// With an empty or short key almost any signature would pass: refuse everything instead.
if (!secret || secret.length < 32) throw new Error('WEBHOOK_SECRET fehlt oder ist kuerzer als 32 Zeichen');

// Limit: ids live in the workflow's static data (one instance, saved after each run).
// Several n8n workers or parallel duplicates need a table with a unique id in Postgres instead.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const now = Date.now();
const WEEK = 7 * 24 * 3600 * 1000;
for (const [id, at] of Object.entries(store.seen)) if (now - at > WEEK) delete store.seen[id];

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const given = String(items[i].json.headers['x-signature'] || '');
  const raw = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('utf8');
  const want = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');
  const valid = given.length === want.length && crypto.timingSafeEqual(Buffer.from(given), Buffer.from(want));
  if (!valid) { out.push({ json: { statusCode: 401, status: 'invalid_signature' } }); continue; }

  let event;
  try { event = JSON.parse(raw); } catch { out.push({ json: { statusCode: 400, status: 'invalid_json' } }); continue; }
  if (!event || !event.id) { out.push({ json: { statusCode: 400, status: 'missing_id' } }); continue; }
  if (store.seen[event.id]) { out.push({ json: { statusCode: 200, status: 'duplicate', id: event.id } }); continue; }

  store.seen[event.id] = now;
  out.push({ json: { statusCode: 200, status: 'accepted', id: event.id, event } });
}
return out;
